import { OneStatusPill } from '@/components/PipelineStatusSelect';
import type { SalesStateView } from '@/lib/leadState';
import { memo } from 'react';
import { WhatsAppStatusBadge } from './WhatsAppStatusBadge';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import type { PhoneFetchStatus } from '@/hooks/useOutreach';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { ExternalLink, MessageSquare, Star, StickyNote, Phone, PhoneCall, Loader2, RefreshCw, CalendarClock, Wand2, Settings2, Scissors, Flower2, Wrench, ClipboardList, ClipboardCheck, MessageSquareText } from 'lucide-react';
import { ContactMethodBadge } from './ContactMethodBadge';
import { NextActionEditor } from './NextActionEditor';
import { LeadEnrichButtons } from './LeadEnrichButtons';
import { SocialLinks } from './SocialLinks';
import type { OutreachLead, LeadStatus, NextActionType, ContactMethod, PipelineStatus } from '@/types/outreach';
import { useLeadPermissions } from '@/hooks/useLeadPermissions';
import { maySetStatus } from '@/lib/access';
import type { AuditRowState } from '@/lib/outreachAuditMap';
import { CONTACT_METHOD_OPTIONS, REP_CONTACT_METHOD_OPTIONS, PIPELINE_STATUS_OPTIONS, OUTREACH_STATUS_OPTIONS, awaitingReplyTooltip } from '@/types/outreach';

interface OutreachMobileCardProps {
  lead: OutreachLead;
  /** The lead's sales state (leadState.salesStateOf), from the table (rowSalesState). The card draws ONE
   *  status pill (the pipeline badge; the stage only in its tooltip, 2026-10-01). */
  salesState?: SalesStateView | null;
  /** Muted campaign-name sub-line under the business name — passed only in the
   *  "All campaigns" view when the lead has a campaign; null/undefined hides it. */
  campaignName?: string | null;
  isSelected: boolean;
  onSelect: (checked: boolean) => void;
  onLeadClick: () => void;
  onStatusChange: (status: LeadStatus) => void;
  onNextActionChange?: (action: NextActionType, date?: string) => void;
  onContactMethodChange?: (method: ContactMethod) => void;
  onPipelineStatusChange?: (status: PipelineStatus) => void;
  onWhatsAppClick: () => void;
  /** Text this lead (SMS). Optional so older callers keep working. */
  onSmsClick?: () => void;
  onCallClick?: () => void;
  onTrack?: () => void;
  readOnly?: boolean;
  showTrackButton?: boolean;
  isHighlighted?: boolean;
  isLastContacted?: boolean;
  onCompleteAction?: () => void;
  phoneFetchStatus?: PhoneFetchStatus;
  onRetryPhoneFetch?: () => void;
  isWalkthroughContacted?: boolean;
  onGenerateSite?: (template: 'barber' | 'salon' | 'plumber', mode?: 'booking_only') => void;
  isGeneratingSite?: boolean;
  onManageSite?: () => void;
  // AI audit control (parity with the desktop row): auditRowState picks the icon, onOpenAudit opens the
  // same popup (HookAuditDialog) in every state — run, progress or result.
  auditState?: AuditRowState;
  onOpenAudit?: () => void;
  /** The row's compact AI check (OutreachAiCheck AiCheckSummary) — the same element as the desktop row. */
  aiCheck?: React.ReactNode;
  onUpdateLead?: (leadId: string, data: Partial<OutreachLead>) => Promise<any>;
}

export const OutreachMobileCard = memo(function OutreachMobileCard({
  salesState,
  lead,
  campaignName,
  isSelected,
  onSelect,
  onLeadClick,
  onStatusChange,
  onNextActionChange,
  onContactMethodChange,
  onPipelineStatusChange,
  onWhatsAppClick,
  onSmsClick,
  onCallClick,
  onTrack,
  readOnly = false,
  showTrackButton = true,
  isHighlighted = false,
  isLastContacted = false,
  onCompleteAction,
  phoneFetchStatus,
  onRetryPhoneFetch,
  isWalkthroughContacted = false,
  onGenerateSite,
  isGeneratingSite = false,
  onManageSite,
  auditState = 'none',
  onOpenAudit,
  aiCheck,
  onUpdateLead,
}: OutreachMobileCardProps) {
  const perms = useLeadPermissions();
  const isPhoneFetching = phoneFetchStatus === 'pending';
  const isPhoneFailed = phoneFetchStatus === 'failed';
  const hasPhone = !!lead.phone;
  const showFetchingState = !hasPhone && isPhoneFetching;

  // Status-based left border color
  const statusBorderColor = (() => {
    const s = lead.status;
    if (s === 'not_contacted') return 'border-l-blue-400/60';
    if (s === 'initial_contact') return 'border-l-amber-500';
    if (s === 'replied') return 'border-l-emerald-500';
    if (s === 'site_sent' || s === 'report_sent') return 'border-l-emerald-400';
    if (s === 'price_given') return 'border-l-sky-500';
    if (s === 'interested') return 'border-l-yellow-500';
    if (s === 'not_interested') return 'border-l-zinc-500';
    if (s === 'payment_received' || s === 'in_delivery' || s === 'completed') return 'border-l-green-600';
    return 'border-l-blue-400/60';
  })();

  return (
    <div 
      className={`py-3.5 px-3.5 border-b border-border/50 border-l-[3px] ${statusBorderColor} ${lead.is_potential_work ? 'bg-primary/5' : ''} ${isHighlighted ? 'ring-1 ring-primary/30 ring-inset bg-primary/5' : ''}`}
      onClick={onLeadClick}
    >
      <div className="flex items-start gap-2.5">
        {/* Left: Checkbox */}
        <div className="pt-0.5" onClick={(e) => e.stopPropagation()}>
          <Checkbox
            checked={isSelected}
            onCheckedChange={onSelect}
            aria-label={`Select ${lead.business_name}`}
            className="h-4 w-4"
          />
        </div>

        {/* Middle: Name + 3 Buttons */}
        <div className="flex-1 min-w-0 space-y-1">
          <div className="flex items-center gap-1.5">
            {lead.country === 'Australia' && (
              <span className="text-xs" title="Australia">🇦🇺</span>
            )}
            <span className="font-bold text-[15px] leading-tight">{lead.business_name}</span>
            {lead.is_potential_work && (
              <Star className="h-3 w-3 text-yellow-500 fill-yellow-500 flex-shrink-0" />
            )}
            {!!lead.notes && lead.notes.trim().length > 0 && (
              <span title="Has a note" className="inline-flex flex-shrink-0">
                <StickyNote className="h-3 w-3 text-muted-foreground/60" />
              </span>
            )}
            <WhatsAppStatusBadge status={lead.whatsapp_status} compact />
          </div>
          {campaignName && (
            <div className="text-[11px] text-muted-foreground leading-none truncate">{campaignName}</div>
          )}
          {hasPhone && (
            <button type="button" onClick={() => onCallClick?.()} className="text-left text-[11px] text-muted-foreground leading-none truncate">
              {lead.phone}
            </button>
          )}
          {/* The AI check, compact: a state word, or ChatGPT x · Gemini y and Call screen. Scores only. */}
          {aiCheck}

          {/* Per-type contact enrichment (email / facebook / instagram) */}
          {/* Enrichment is admin work (perms.enrichLeads), as on the desktop row. */}
          {/* The one Socials line (2026-09-30), both roles. */}
          <SocialLinks lead={lead} size="xs" />
          {onUpdateLead && perms.enrichLeads && (
            <div className="pt-0.5">
              <LeadEnrichButtons lead={lead} onUpdate={onUpdateLead} socials={false} />
            </div>
          )}

          {/* Three dropdowns: Contact Method, Status, Next Action */}
          {!readOnly && (
            <div className="space-y-1" onClick={(e) => e.stopPropagation()}>
              {/* Row 1: Contact Method + Status */}
              <div className="flex items-center gap-1.5 flex-wrap">
                {/* Contact Method */}
                {onContactMethodChange && (
                  <Select
                    value={lead.contact_method || ''}
                    onValueChange={(v) => {
                      onContactMethodChange(v as ContactMethod);
                    }}
                  >
                    <SelectTrigger 
                      className="w-auto h-auto p-0 border-0 bg-transparent focus:ring-0"
                      {...(isLastContacted ? { 'data-walkthrough-step': 'contact-method', 'data-walkthrough': 'contact-method' } : {})}
                    >
                      <ContactMethodBadge method={lead.contact_method as ContactMethod} compact />
                    </SelectTrigger>
                    <SelectContent>
                      {(perms.editLeadRecord ? CONTACT_METHOD_OPTIONS : REP_CONTACT_METHOD_OPTIONS).map((opt) => (
                        <SelectItem key={opt.value} value={opt.value}>
                          {opt.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
                {/* Read-only for a role that cannot set the tag (the desktop row does the same). */}
                {!onContactMethodChange && lead.contact_method && (
                  <ContactMethodBadge method={lead.contact_method as ContactMethod} compact />
                )}

                {/* Pipeline Status */}
                {onPipelineStatusChange && (
                  <Select
                    value={lead.status || 'not_contacted'}
                    onValueChange={(v) => {
                      const status = v as PipelineStatus;
                      // "Interested" sets the star inside onPipelineStatusChange (one write, History).
                      onPipelineStatusChange(status);
                    }}
                  >
                    <SelectTrigger 
                      className="w-auto h-auto p-0 border-0 bg-transparent focus:ring-0"
                      title={lead.status === 'awaiting_reply'
                        ? awaitingReplyTooltip(lead.whatsapp_template, lead.whatsapp_sent_at)
                        : undefined}
                      {...(isLastContacted ? { 'data-walkthrough-step': 'pipeline-status', 'data-walkthrough': 'pipeline-status' } : {})}
                    >
                      <OneStatusPill status={lead.status} stage={salesState} compact />
                    </SelectTrigger>
                    <SelectContent>
                      {PIPELINE_STATUS_OPTIONS.map((opt) => (
                        <SelectItem key={opt.value} value={opt.value} disabled={!maySetStatus(perms, opt.value)}>
                          {opt.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
                {!onPipelineStatusChange && <OneStatusPill status={lead.status} stage={salesState} compact />}
              </div>

              {/* Row 2: Next Action (always below) */}
              {onNextActionChange && (
                <div>
                  <NextActionEditor lead={lead} />
                </div>
              )}
            </div>
          )}
        </div>

        {/* Right: Action buttons */}
        <div className="flex flex-col gap-0.5 flex-shrink-0" onClick={(e) => e.stopPropagation()}>
          {showFetchingState ? (
            <div className="flex items-center gap-1.5 px-2 py-2">
              <Loader2 className="h-3.5 w-3.5 animate-spin text-muted-foreground" />
              <span className="text-[10px] text-muted-foreground">Fetching...</span>
            </div>
          ) : (
            <>
              {/* Row 1: Maps, Call */}
              <div className="flex items-center gap-0.5">
                {(lead.google_maps_url || ((lead as any).place_id ? `https://www.google.com/maps/place/?q=place_id:${(lead as any).place_id}` : null)) && (
                  <Button variant="ghost" size="icon" className="h-7 w-7 text-blue-500 hover:text-blue-400 hover:bg-blue-500/10" asChild>
                    <a href={lead.google_maps_url || `https://www.google.com/maps/place/?q=place_id:${(lead as any).place_id}`} target="_blank" rel="noopener noreferrer">
                      <ExternalLink className="h-3.5 w-3.5" />
                    </a>
                  </Button>
                )}
                {hasPhone ? (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-amber-500 hover:text-amber-400 hover:bg-amber-500/10">
                        <Phone className="h-3.5 w-3.5" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="min-w-[160px]">
                      {/* Call opens the lead popup with the number to dial on your own phone — never a tel: link
                          (2026-10-07: on a laptop tel: opens WhatsApp Desktop). */}
                      <DropdownMenuItem className="flex items-center gap-2 cursor-pointer" onClick={() => onCallClick?.()} data-testid="outreach-call">
                        <PhoneCall className="h-4 w-4" />
                        Call
                      </DropdownMenuItem>
                      {/* ⛔ WAS A wa.me LINK LABELLED "WhatsApp Call" — the desktop row's twin, and
                          wrong the same way. wa.me opens a CHAT, so this was a second way to message
                          someone OUTSIDE the app: no whatsapp_messages row, no thread, no reply
                          window, invisible to every CRM count. Now the in-app thread, through the
                          SAME onWhatsAppClick the green button below uses, so the two cannot drift.
                          ⛔ onCallClick IS DELIBERATELY NOT CALLED. It was on the old link, and
                          keeping it "to preserve behaviour" would RECORD A CALL THAT NEVER HAPPENS
                          (contact_method='call' + a logged call attempt) and race the 'whatsapp'
                          write for the same field. This item is not a call any more. */}
                      <DropdownMenuItem
                        className="flex items-center gap-2 cursor-pointer"
                        onClick={() => onWhatsAppClick?.()}
                      >
                        <Phone className="h-4 w-4 text-green-500" />
                        WhatsApp thread
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                ) : isPhoneFailed ? (
                  <Button variant="ghost" size="icon" className="h-7 w-7 text-destructive" onClick={onRetryPhoneFetch}>
                    <RefreshCw className="h-3.5 w-3.5" />
                  </Button>
                ) : null}
              </div>
              {/* Row 2: WhatsApp, Track */}
              <div className="flex items-center gap-0.5">
                {hasPhone ? (
                  <div className="flex items-center gap-0.5" data-walkthrough={lead.outreach_attempts === 0 && !isWalkthroughContacted ? 'contact' : undefined}>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7 text-green-500 hover:text-green-400 hover:bg-green-500/10"
                      onClick={() => { window.dispatchEvent(new CustomEvent('outreach-first-contact-click', { detail: { method: 'whatsapp' } })); onWhatsAppClick?.(); }}
                    >
                      <MessageSquare className="h-3.5 w-3.5" />
                    </Button>
                    {onSmsClick && (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-blue-500 hover:bg-blue-500/10 hover:text-blue-400" onClick={onSmsClick} title="Send a text message" aria-label="Send a text message" data-testid="outreach-sms-mobile">
                        <MessageSquareText className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </div>
                ) : null}
                {!readOnly && showTrackButton && onTrack && (
                  lead.is_potential_work ? (
                    <Star className="h-3.5 w-3.5 text-yellow-500 fill-yellow-500 mx-1" />
                  ) : (
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7 text-yellow-500 hover:text-yellow-400 hover:bg-yellow-500/10"
                      onClick={onTrack}
                      {...(isLastContacted ? { 'data-walkthrough-step': 'track-star', 'data-walkthrough': 'track' } : {})}
                    >
                      <Star className="h-3.5 w-3.5" />
                    </Button>
                  )
                )}
                {onManageSite && (
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7 text-emerald-400 hover:text-emerald-300 hover:bg-emerald-500/10"
                    onClick={onManageSite}
                    title="Manage site (admin)"
                  >
                    <Settings2 className="h-3.5 w-3.5" />
                  </Button>
                )}
                {onGenerateSite && (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-violet-400 hover:text-violet-300 hover:bg-violet-500/10"
                        disabled={isGeneratingSite}
                        title="Generate site (admin)"
                        onClick={(e) => e.stopPropagation()}
                      >
                        {isGeneratingSite ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <Wand2 className="h-3.5 w-3.5" />
                        )}
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent
                      align="end"
                      className="min-w-[160px]"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <DropdownMenuLabel className="text-xs text-muted-foreground">Full site</DropdownMenuLabel>
                      <DropdownMenuItem onSelect={() => onGenerateSite('barber')}>
                        <Scissors className="h-4 w-4 mr-2" />
                        Barber site
                      </DropdownMenuItem>
                      <DropdownMenuItem onSelect={() => onGenerateSite('salon')}>
                        <Flower2 className="h-4 w-4 mr-2" />
                        Salon site
                      </DropdownMenuItem>
                      <DropdownMenuItem onSelect={() => onGenerateSite('plumber')}>
                        <Wrench className="h-4 w-4 mr-2" />
                        Plumber site
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuLabel className="text-xs text-muted-foreground">Booking page (has a website)</DropdownMenuLabel>
                      <DropdownMenuItem onSelect={() => onGenerateSite('barber', 'booking_only')}>
                        <CalendarClock className="h-4 w-4 mr-2" />
                        Barber booking page
                      </DropdownMenuItem>
                      <DropdownMenuItem onSelect={() => onGenerateSite('salon', 'booking_only')}>
                        <CalendarClock className="h-4 w-4 mr-2" />
                        Salon booking page
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                )}
                {/* AI audit control — parity with the desktop row (auditsByLead state). */}
                {onOpenAudit ? (
                  <Button
                    variant="ghost"
                    size="icon"
                    className={auditState === 'done' ? 'h-7 w-7 text-emerald-400 hover:text-emerald-300 hover:bg-emerald-500/10' : 'h-7 w-7 text-sky-400 hover:text-sky-300 hover:bg-sky-500/10'}
                    onClick={onOpenAudit}
                    title={auditState === 'done' ? 'Audit complete — open the result' : auditState === 'running' ? 'Audit running — open to see progress' : 'Run the AI visibility check'}
                    aria-label={auditState === 'done' ? 'Audit complete' : auditState === 'running' ? 'Audit running' : 'Run audit'}
                  >
                    {auditState === 'done' ? <ClipboardCheck className="h-3.5 w-3.5" /> : auditState === 'running' ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <ClipboardList className="h-3.5 w-3.5" />}
                  </Button>
                ) : null}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
});
