import { useState, useMemo, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import {
  Dialog,
  DialogContent,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Callout, DialogHero } from '@/components/operator/ui';
import { MessageSquare, Send, AlertTriangle, RotateCcw, Loader2 } from 'lucide-react';
import { generateWhatsAppUrl, fillTemplate, hasLinkToken } from '@/lib/leadUtils';
import { siteLinkGuard } from '@/lib/whatsappTemplates';
import type { SupabaseClient } from '@supabase/supabase-js';
import { TemplatePicker } from '@/components/TemplatePicker';
import { useAutoRotateTemplate } from '@/hooks/useAutoRotateTemplate';
import { AutoRotateToggle } from '@/components/AutoRotateToggle';
import { useToast } from '@/hooks/use-toast';

interface SingleWhatsAppDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  lead: { phone: string; business_name: string; id?: string; whatsapp_status?: string | null; status?: string; country?: string | null } | null;
  /** Called when user clicks "Open WhatsApp" — signals a send happened (confirmation handled externally) */
  onSent?: (leadId: string, channel: 'whatsapp') => void;
  /** Launch-pad: pre-fill this template content fresh on open (overrides saved/localStorage). */
  initialTemplate?: string | null;
  /** Launch-pad: the barber's /s/ link to substitute for {{link}}. If omitted, the
   *  lead's own site link is resolved automatically on open. */
  shareLink?: string | null;
}

const DEFAULT_TEMPLATE = `Hi, is this the right number for {{business_name}}?`;
const STORAGE_KEY = 'leadfinder_whatsapp_template';

export function SingleWhatsAppDialog({ open, onOpenChange, lead, onSent, initialTemplate, shareLink }: SingleWhatsAppDialogProps) {
  const handleOpenChange = (v: boolean) => {
    onOpenChange(v);
    if (!v) {
      // Notify walkthrough that the contact panel was closed
      window.dispatchEvent(new CustomEvent('demo-checklist-contact-panel-closed'));
    }
  };
  const [template, setTemplate] = useState(DEFAULT_TEMPLATE);
  const [isModified, setIsModified] = useState(false);
  const [showTemplateNudge] = useState(false);
  const [isSending, setIsSending] = useState(false);

  const { autoOn, toggleAuto, getNextTemplate } = useAutoRotateTemplate();
  const { toast } = useToast();



  // On open: a launch (initialTemplate) always wins and opens FRESH — ignores
  // auto-rotate and localStorage so a previous barber's content can't leak.
  useEffect(() => {
    if (!open) return;
    setIsSending(false);
    if (initialTemplate != null) {
      setTemplate(initialTemplate);
      setIsModified(true);
      return;
    }
    if (autoOn) {
      const next = getNextTemplate(template);
      setTemplate(next);
      setIsModified(next !== DEFAULT_TEMPLATE);
      localStorage.setItem(STORAGE_KEY, next);
    } else {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        setTemplate(saved);
        setIsModified(saved !== DEFAULT_TEMPLATE);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, initialTemplate, lead?.id]);

  /* {{link}} resolves to the link the CALLER passed, and nothing else.
     ⛔ It used to fall back to querying generated_sites for this lead's barber share_token and
     building a yoursites.uk/s/<token> URL — the barber product, deleted 2026-09-09. With no site
     to look up, an absent shareLink now simply means "no link", which siteLinkGuard already
     handles: a template needing {{link}} is refused rather than sent with a dead URL. */
  const resolvedLink = shareLink ?? null;
  const linkLoading = false;

  // Check WhatsApp status when dialog opens — if 'no', show toast and close
  useEffect(() => {
    if (!open || !lead) return;
    if (lead.whatsapp_status === 'no') {
      toast({
        title: 'Not on WhatsApp',
        description: `${lead.business_name} was previously marked as not on WhatsApp. Try a call instead.`,
      });
      handleOpenChange(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, lead?.whatsapp_status]);

  const handleTemplateChange = (value: string) => {
    setTemplate(value);
    setIsModified(value !== DEFAULT_TEMPLATE);
    localStorage.setItem(STORAGE_KEY, value);
  };

  const handleReset = () => {
    setTemplate(DEFAULT_TEMPLATE);
    setIsModified(false);
    localStorage.setItem(STORAGE_KEY, DEFAULT_TEMPLATE);
  };

  const previewMessage = useMemo(() => {
    if (!lead) return template;
    return fillTemplate(template, { businessName: lead.business_name, link: resolvedLink });
  }, [template, lead, resolvedLink]);

  // Guard: if this template references {{link}} but the lead has no resolvable site link,
  // block the send — fillTemplate leaves "{{link}}" literal, so sending would ship a broken
  // link. Decision + reason come from the SHARED siteLinkGuard (same rule the Inbox picker
  // uses). linkResolving keeps the button disabled while the async token lookup is in flight
  // (so it can't send before the link resolves); linkMissing is the confirmed no-token case.
  const needsLink = useMemo(() => hasLinkToken(template), [template]);
  const linkGuard = siteLinkGuard(needsLink, resolvedLink);
  const linkResolving = needsLink && linkLoading;
  const linkMissing = !linkResolving && !linkGuard.ok;
  const linkBlocked = linkResolving || linkMissing;

  const handleSend = async () => {
    if (!lead || !lead.phone || isSending || linkBlocked) return;
    setIsSending(true);
    
    const message = fillTemplate(template, { businessName: lead.business_name, link: resolvedLink });
    const url = generateWhatsAppUrl(lead.phone, message, lead.country);

    // Store pending WhatsApp check markers in localStorage
    if (lead.id && (!lead.whatsapp_status || lead.whatsapp_status === 'unknown')) {
      localStorage.setItem('pending_whatsapp_check_lead_id', lead.id);
      localStorage.setItem('pending_whatsapp_check_started_at', Date.now().toString());
      localStorage.setItem('pending_whatsapp_check_lead_name', lead.business_name);
    }

    window.open(url, '_blank');
    // demo-checklist-contact dispatched by OutreachTable on button click
    window.dispatchEvent(new CustomEvent('challenge-contact-sent', { detail: { leadId: lead.business_name } }));

    // Signal send happened — confirmation & logAttempt handled externally
    if (lead.id && onSent) {
      onSent(lead.id, 'whatsapp');
    }

    handleOpenChange(false);

    supabase.rpc('log_usage_event', {
      p_event_type: 'message_sent',
      p_meta: {
        channel: 'whatsapp',
        business_name: lead.business_name,
        source: 'single-whatsapp-dialog',
      },
    }).then(({ error }) => { if (error) console.error('Usage tracking failed:', error); });
  };

  if (!lead) return null;

  const hasPhone = Boolean(lead.phone);

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHero
          icon={MessageSquare}
          tone="green"
          title="WhatsApp Message"
          subtitle={<>To <span className="font-semibold text-foreground">{lead.business_name}</span></>}
        />

        {!hasPhone ? (
          <Callout tone="amber" icon={AlertTriangle}>
            This business doesn't have a phone number on file.
          </Callout>
        ) : (
          <div className="space-y-5">
            {/* Template Editor */}
            <div>
              <div className="flex items-center justify-between mb-2">
                <Label htmlFor="template" className="text-sm font-semibold">Initial Message</Label>
                <div className="flex items-center gap-2">
                  {isModified && !autoOn && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handleReset}
                      className="h-7 text-xs text-muted-foreground hover:text-foreground"
                    >
                      <RotateCcw className="h-3 w-3 mr-1" />
                      Reset
                    </Button>
                  )}
                  <AutoRotateToggle autoOn={autoOn} onToggle={toggleAuto} />
                </div>
              </div>
              <TemplatePicker 
                onSelectTemplate={(content, templateId) => {
                  handleTemplateChange(content);
                  if (templateId === 'default-0') {
                    toggleAuto(true);
                  } else {
                    if (autoOn) toggleAuto(false);
                  }
                }} 
                templateType="text" 
                isWalkthrough={false}
              />
              <Textarea
                id="template"
                value={template}
                onChange={(e) => {
                  handleTemplateChange(e.target.value);
                  if (autoOn) toggleAuto(false);
                }}
                rows={4}
                className="font-mono text-sm mt-2"
              />
              {autoOn && (
                <p className="text-[11px] text-muted-foreground mt-1.5">
                  Rotating between 6 proven opening messages to reduce repetition and improve reply rates.
                </p>
              )}
            </div>

            {/* Live Preview */}
            <div>
              <Label className="flex items-center gap-1.5 mb-2 text-sm font-semibold">
                <span>📝</span>
                Preview
              </Label>
              <div className="p-3 bg-green-500/10 border border-green-500/30 rounded-lg text-sm whitespace-pre-wrap">
                {previewMessage}
              </div>
            </div>

            {/* No-link guard: this template needs a site link but the lead has none. */}
            {linkBlocked && (
              <p className="flex items-center gap-1.5 text-[11px] text-amber-700 dark:text-amber-300">
                <AlertTriangle className="h-3 w-3 shrink-0" />
                {linkResolving
                  ? 'Checking for this lead’s site link…'
                  : linkGuard.reason}
              </p>
            )}

            {/* Compliance note */}
            <p className="text-[10px] text-muted-foreground/50 text-center">
              Ensure outreach complies with platform and local regulations.
            </p>
          </div>
        )}

        <DialogFooter className="gap-2 flex-row justify-end">
          <Button variant="outline" onClick={() => {
            handleOpenChange(false);
          }}>
            Cancel
          </Button>
          {hasPhone && (
            <Button onClick={handleSend} disabled={isSending || linkBlocked} className="bg-green-600 hover:bg-green-700 whitespace-nowrap">
              {isSending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Opening...
                </>
              ) : (
                <>
                  <Send className="h-4 w-4 mr-2" />
                  Open WhatsApp
                </>
              )}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
